import{_ as t,o as r,c as i,a5 as o}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"调用数据库","description":"","frontmatter":{"title":"调用数据库","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/调用数据库.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/调用数据库.md"}'),p={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/调用数据库.md"};function a(n,e,s,c,d,l){return r(),i("div",null,[...e[0]||(e[0]=[o(`<div><ul><li><code>Springboot</code></li><li><code>springtest</code></li><li><code>Lombok</code></li><li>数据库： <ul><li><code>Jdbc</code></li><li><code>Mysql</code></li><li><code>Mybatis</code></li><li><code>Mybatisplus</code></li></ul></li><li>文档类：<code>springdoc</code></li><li><code>Common</code></li></ul><p>首先建立实体类（跟数据库保持一致） <code>entity</code></p><p>package com.mincheng.construction.entity; public class User { private int id; private String nickName; private String userName; private String password; public User(int id, String nickName, String userName, String password) { this.id = id; this.nickName = nickName; this.userName = userName; this.password = password; } public int getId() { return id; } public void setId(int id) { this.id = id; } public String getNickName() { return nickName; } public void setNickName(String nickName) { this.nickName = nickName; } public String getUserName() { return userName; } public void setUserName(String userName) { this.userName = userName; } public void setPassword(String password) { this.password = password; } } 在数据库中建立相应的表和字段：</p><p><code>mapper</code> 操作数据库动作</p><p>package com.mincheng.construction.mapper; import com.mincheng.construction.entity.User; import org.apache.ibatis.annotations.Mapper; import java.util.List;</p><p>@Mapper public interface UserMapper { // 定义操作数据库为查找所有用户</p><pre><code>List\\&lt;User\\&gt; findAll();
</code></pre><p>} 建立<code>mapper.xml</code>（<code>sql</code>语句）</p><p>在<code>resource</code>文件下 <code>mapper.xml</code>配置详解</p><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot; ?&gt; &lt;!DOCTYPE mapper PUBLIC &quot;-<a href="//mybatis.org//DTD" target="_blank" rel="noreferrer">//mybatis.org//DTD</a> Mapper 3.0//EN&quot; &quot;<a href="http://mybatis.org/dtd/mybatis-3-mapper.dtd" target="_blank" rel="noreferrer">http://mybatis.org/dtd/mybatis-3-mapper.dtd</a>&quot;&gt; &lt;!-- namespace ==对应哪个==<code>mapper</code>==文件==</p><p>--&gt; &lt;mapper namespace=&quot;com.mincheng.construction.mapper.UserMapper&quot;&gt; &lt;!-- id ==对应==<code>mapper</code>==里面的方法名== <code>resultType</code>==对应实体类的数据库类==</p><p>--&gt; &lt;select id=&quot;findAll&quot; resultType=&quot;com.mincheng.construction.entity.User&quot;&gt; select * from user; &lt;/select&gt; &lt;/mapper&gt;</p><p><code>service</code>操作导出数据库数据</p><p>package com.mincheng.construction.service; import com.mincheng.construction.entity.User; import com.mincheng.construction.mapper.UserMapper; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import java.util.List; @Service public class UserService { @Autowired private UserMapper userMapper; public List&lt;User&gt; findAll(){ return userMapper.findAll(); } } 检查确定</p><p><code>mapper/UserMapper</code></p><p>里面加了<code>@mapper</code>注解</p><p>最后<code>controller</code>里面设置接口</p><p>package com.test.demo.controller;</p><p>import com.test.demo.entity.User; import com.test.demo.service.UserService; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.bind.annotation.CrossOrigin; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RestController;</p><p>import java.util.List;</p><p>@RestController public class userController { @Autowired private UserService userService;</p><pre><code>@CrossOrigin
@RequestMapping(&quot;/abc&quot;)
public Animal getName()\\{
    return new Animal(&quot;hml&quot;,5);
\\}
@CrossOrigin
@RequestMapping(&quot;/abcd&quot;)
public List\\&lt;User\\&gt; getUser()\\{
     return userService.findAll();
\\}
</code></pre><p>} 效果：</p></div>`,1)])])}const g=t(p,[["render",a]]);export{u as __pageData,g as default};
